    history(partNo: string, limit?: number): Movement[] {
        const key = keyOf(partNo);
        if (limit !== undefined && !wholeAndAtLeast(limit, 1)) {
            throw new RangeError("limit must be a whole number of 1 or more");
        }
        const all = this.moves.filter((m) => m.partNo === key);
        const latest = limit === undefined ? all : all.slice(-limit);
        return latest.map((m) => ({ ...m }));
    }
